if arguments.options["--provider"] == "play" {
    let app = try ApplicationConfiguration.load(root).application
    let request = try PlayTestingRequest.parse(words: words, options: arguments.options, applicationID: app)
    let report = try await PlayReleaseStatus().status(
        request: request,
        token: ProcessInfo.processInfo.environment["MIXER_PLAY_BEARER_TOKEN"] ?? ""
    )
    try output(report)
    exit(report.exitCode)
}
